// CopyQ "Search all tabs" installer (generated by build.sh — edit search.js instead).
// Usage (CopyQ must be running):
//   copyq eval "$(cat install.js)"
// Idempotent: updates the command with internalId=cross_tab_search, or adds it if missing.
// Shortcut 'ctrl+f4' = ⌘+F4 on macOS (Qt maps ctrl to Command), Ctrl+F4 on Windows/Linux.
var B = '';
var CMD = "copyq: eval(str(fromBase64('" + B + "')))";
var cs = commands();
var found = false;
for (var i = 0; i < cs.length; ++i) {
  if (cs[i].internalId === 'cross_tab_search') {
    found = true;
    cs[i].cmd = CMD;
    cs[i].globalShortcuts = ['ctrl+f4'];
    cs[i].isGlobalShortcut = true;
    cs[i].inMenu = false;
    cs[i].name = 'Search all tabs';
    cs[i].enable = true;
  }
}
if (!found) {
  cs.push({
    name: 'Search all tabs',
    internalId: 'cross_tab_search',
    cmd: CMD,
    isGlobalShortcut: true,
    globalShortcuts: ['ctrl+f4'],
    inMenu: false,
    enable: true
  });
}
setCommands(cs);
found ? 'updated' : 'installed';
